/// Strongly retained for the whole recording: stream, recording output,
/// and delegate must all stay alive or capture stops.
@available(macOS 15, *)
@MainActor
final class ScreenRecordingSession {
    let id: UUID
    let stream: any RecordingCaptureStream
    let recordingOutput: SCRecordingOutput?
    let forwarder: ScreenRecordingForwarder?
    var displayID: CGDirectDisplayID
    let tempURL: URL
    /// Frame rate captured once at recording startup.
    let frameRate: Int
    var startUptime: TimeInterval

    var candidateDisplayID: CGDirectDisplayID?
    var candidateSince: TimeInterval = 0
    var filterUpdateInProgress = false
    var writerStarted = false
    var finalizationStarted = false
    var finalized = false
    /// Set only by the recording-output delegate on successful finalization,
    /// never by the finalize timeout.
    var didFinishRecording = false
    var finalizeContinuation: CheckedContinuation<Void, Never>?

    init(id: UUID, stream: any RecordingCaptureStream, recordingOutput: SCRecordingOutput? = nil,
         forwarder: ScreenRecordingForwarder? = nil, displayID: CGDirectDisplayID,
         tempURL: URL, frameRate: Int, startUptime: TimeInterval) {
        self.id = id
        self.stream = stream
        self.recordingOutput = recordingOutput
        self.forwarder = forwarder
        self.displayID = displayID
        self.tempURL = tempURL
        self.frameRate = frameRate
        self.startUptime = startUptime
    }
}

/// SCRecordingOutput takes its delegate in the initializer (no writable
/// delegate property) and calls it off the main thread, so this forwarder
/// holds the session id and hops back to the main actor.
@available(macOS 15, *)
final class ScreenRecordingForwarder: NSObject, SCRecordingOutputDelegate, SCStreamDelegate {
    weak var service: ScreenRecordingService?
    let sessionID: UUID

    init(service: ScreenRecordingService, sessionID: UUID) {
        self.service = service
        self.sessionID = sessionID
    }

    func recordingOutputDidStartRecording(_ recordingOutput: SCRecordingOutput) {
        let id = sessionID
        Task { [weak service] in await service?.handleRecordingDidStart(sessionID: id) }
    }

    func recordingOutputDidFinishRecording(_ recordingOutput: SCRecordingOutput) {
        let id = sessionID
        Task { [weak service] in await service?.handleRecordingDidFinish(sessionID: id) }
    }

    func recordingOutput(_ recordingOutput: SCRecordingOutput, didFailWithError error: Error) {
        let id = sessionID
        Task { [weak service] in await service?.handleRecordingDidFail(sessionID: id, error: error) }
    }

    func stream(_ stream: SCStream, didStopWithError error: Error) {
        let id = sessionID
        Task { [weak service] in await service?.handleStreamDidStop(sessionID: id, error: error) }
    }
}

private extension NSScreen {
    var recordingDisplayID: CGDirectDisplayID? {
        guard let number = deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? NSNumber else {
            return nil
        }
        return CGDirectDisplayID(number.uint32Value)
    }
}

import AppKit

struct WorkflowEncodedImageResult {
    let data: Data
    let outputURL: URL
}

enum WorkflowImagePersistenceLogic {
    typealias UniqueURLResolver = (_ proposedName: String, _ directory: URL) -> URL

    /// Originals larger than this are not embedded, to avoid bloating saved files.
    /// Generous enough that real screenshots (incl. full-screen Retina PNGs)
    /// always round-trip; only pathologically large originals are skipped.
    static let maxEmbeddedOriginalBytes = 50 * 1024 * 1024

    static func encodedImageData(from image: NSImage,
                                 originalURL: URL,
                                 cleanOriginalPNG: Data? = nil,
                                 prompt: String? = nil,
                                 editorState: EditorCanvasState? = nil,
                                 uniqueURL: UniqueURLResolver) -> WorkflowEncodedImageResult? {
        // PNG-only: every image is encoded as PNG regardless of the original
        // file's extension.
        let ext = originalURL.pathExtension.lowercased()

        guard let bitmap = ScreenshotServiceCoreLogic.bitmapRepresentation(from: image) else { return nil }
        guard var data = bitmap.representation(using: .png, properties: [:]) else { return nil }

        // Round-trip metadata: embed the clean original + prompt and/or editable
        // canvas state when present.
        if let prompt, !prompt.isEmpty,
           let cleanOriginalPNG, cleanOriginalPNG.count < maxEmbeddedOriginalBytes,
           let embedded = PNGMetadata.embed(intoPNG: data,
                                            originalPNG: cleanOriginalPNG,
                                            prompt: prompt,
                                            editorState: editorState) {
            data = embedded
        } else if let editorState,
                  editorState.baseImagePNG.count < maxEmbeddedOriginalBytes,
                  let embedded = PNGMetadata.embed(intoPNG: data, editorState: editorState) {
            data = embedded
        }

        let outputURL: URL
        if ext != "png" && !ext.isEmpty {
            // Original wasn't a PNG (e.g. an opened JPEG/HEIC). Rewrite as .png.
            let proposedName = originalURL.deletingPathExtension().lastPathComponent + ".png"
            outputURL = uniqueURL(proposedName, originalURL.deletingLastPathComponent())
        } else {
            outputURL = originalURL
        }

        return WorkflowEncodedImageResult(data: data, outputURL: outputURL)
    }

    static func writeEncodedImageData(_ data: Data,
                                      to outputURL: URL,
                                      originalURL: URL,
                                      fileManager: FileManager = .default) throws -> URL {
        try data.write(to: outputURL, options: .atomic)

        if outputURL != originalURL, fileManager.fileExists(atPath: originalURL.path) {
            try? fileManager.removeItem(at: originalURL)
        }

        return outputURL
    }
}

import AppKit

struct WorkflowReopenMetadata {
    var cleanOriginalPNG: Data?
    var image: NSImage?
    var prompt: String?
    var editorState: EditorCanvasState?
    var outerImageIsUnsafe: Bool = false
}

enum WorkflowReopenMetadataLogic {
    /// Resolves the clean baseline image, in-memory image, and pre-filled prompt
    /// for a workflow, recovering embedded round-trip metadata on reopen.
    ///
    /// Invalid editor metadata is ignored so the flattened visible image still
    /// opens instead of crashing or rejecting a usable PNG. An unsafe outer
    /// image is rejected without decoding.
    static func resolve(fileURL: URL,
                        initialImage: NSImage?,
                        limits: ImageSafetyLimits = .runtime) -> WorkflowReopenMetadata {
        // Fresh capture: the in-memory image is already the clean original.
        // Snapshot it as PNG so it can be embedded as the round-trip baseline.
        if let initialImage {
            return WorkflowReopenMetadata(
                cleanOriginalPNG: ScreenshotServiceCoreLogic.pngData(from: initialImage),
                image: nil,
                prompt: nil,
                editorState: nil
            )
        }

        switch ImageSafety.inspectFile(at: fileURL, limits: limits) {
        case .tooLarge:
            return WorkflowReopenMetadata(outerImageIsUnsafe: true)
        case .notAnImage:
            return WorkflowReopenMetadata()
        case .safe:
            break
        }

        guard let fileData = ImageSafety.boundedFileData(at: fileURL, limits: limits) else {
            return WorkflowReopenMetadata(outerImageIsUnsafe: true)
        }
        return resolve(fileData: fileData, limits: limits)
    }

    static func resolve(fileData: Data,
                        limits: ImageSafetyLimits = .runtime) -> WorkflowReopenMetadata {
        switch ImageSafety.inspectData(fileData, limits: limits) {
        case .tooLarge:
            return WorkflowReopenMetadata(outerImageIsUnsafe: true)
        case .notAnImage:
            return WorkflowReopenMetadata()
        case .safe:
            break
        }

        let editorState = PNGMetadata.extractEditorState(fromPNG: fileData, limits: limits)
        if let extracted = PNGMetadata.extract(fromPNG: fileData, limits: limits) {
            let image = editorState.flatMap { ImageSafety.loadImageIfSafe($0.baseImagePNG, limits: limits) }
                ?? ImageSafety.loadImageIfSafe(extracted.originalPNG, limits: limits)
            return WorkflowReopenMetadata(
                cleanOriginalPNG: extracted.originalPNG,
                image: image,
                prompt: extracted.prompt,
                editorState: editorState
            )
        }
        if let editorState {
            return WorkflowReopenMetadata(
                cleanOriginalPNG: nil,
                image: ImageSafety.loadImageIfSafe(editorState.baseImagePNG, limits: limits),
                prompt: nil,
                editorState: editorState
            )
        }
        // Plain PNG with no (or unusable) metadata: the file itself is the
        // clean baseline. The outer image was already inspected as safe.
        if PNGMetadata.isPNG(fileData) {
            return WorkflowReopenMetadata(
                cleanOriginalPNG: fileData,
                image: nil,
                prompt: nil,
                editorState: nil
            )
        }
        return WorkflowReopenMetadata()
    }
}

import Foundation

enum UniqueFileURLLogic {
    static func uniqueURL(forProposedName name: String,
                          in directory: URL,
                          fileExists: (String) -> Bool) -> URL {
        let baseName = (name as NSString).deletingPathExtension
        let ext = (name as NSString).pathExtension

        var attempt = 1
        while true {
            let fileName: String
            if attempt == 1 {
                fileName = name
            } else {
                let suffix = "_\(attempt)"
                if ext.isEmpty {
                    fileName = baseName + suffix
                } else {
                    fileName = baseName + suffix + "." + ext
                }
            }

            let url = directory.appendingPathComponent(fileName)
            if !fileExists(url.path) {
                return url
            }
            attempt += 1
        }
    }
}

import AppKit

/// Manages the NSStatusItem (menubar icon and menu).
final class TrayService {
    private let statusItem: NSStatusItem
    private let onShowSettings: () -> Void

    init(onShowSettings: @escaping () -> Void) {
        self.onShowSettings = onShowSettings
        statusItem = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
        restoreStatusImage()
        // AppKit anchors the menu to its status item, including across displays.
        statusItem.menu = makeMenu()
    }

    private func makeMenu() -> NSMenu {
        let menu = NSMenu()
        AppTheme.apply(to: menu)

        menu.addItem(NSMenuItem(title: "Settings", action: #selector(didSelectSettings), keyEquivalent: ""))
        menu.addItem(NSMenuItem.separator())
        let quitItem = NSMenuItem(title: "Quit", action: #selector(didSelectQuit), keyEquivalent: "q")
        quitItem.keyEquivalentModifierMask = [.command]
        menu.addItem(quitItem)

        menu.items.forEach { item in
            item.target = self
        }

        return menu
    }

    /// Compact elapsed seconds, capped at the recording limit.
    @MainActor
    func updateRecording(state: ScreenRecordingService.State, elapsed: TimeInterval) {
        guard let button = statusItem.button else { return }
        switch state {
        case .idle:
            button.attributedTitle = NSAttributedString(string: "")
            button.contentTintColor = nil
            restoreStatusImage()
        case .starting:
            setRecordingTitle("0")
        case .recording, .stopping:
            let limit = Int(ScreenRecordingService.maxDuration)
            let seconds = min(limit, max(0, Int(elapsed)))
            setRecordingTitle(String(seconds))
        }
    }

    private func setRecordingTitle(_ title: String) {
        guard let button = statusItem.button else { return }
        button.image = nil
        button.attributedTitle = NSAttributedString(string: title, attributes: [
            .foregroundColor: NSColor.systemRed,
            .font: NSFont.monospacedDigitSystemFont(ofSize: NSFont.systemFontSize, weight: .medium)
        ])
    }

    private func restoreStatusImage() {
        guard let button = statusItem.button else { return }
        if #available(macOS 11.0, *) {
            button.image = NSImage(systemSymbolName: "camera", accessibilityDescription: "Zoomies")
        }
    }

    @objc private func didSelectSettings() {
        onShowSettings()
    }

    @objc private func didSelectQuit() {
        NSApp.terminate(nil)
    }
}
